
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_revscan0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_revscan0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.663449819592210e+00, -3.589286171173277e+00, -3.485334273145537e+00, -3.341269738767140e+00, -3.144823625626664e+00, -2.883067570717047e+00, -2.545512384552991e+00, -2.129711392202449e+00, -1.648755157354140e+00, -1.129304147827798e+00, -6.379113439510220e-01, -4.601824651121670e-01, -4.716997388665223e-01, -3.999712180663886e-01, -2.727585858256072e-01, -1.474802246796895e-01, -5.859864526934965e-02, -1.560712465949968e-02, -2.183894811554861e-03, -1.040244043253764e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


